  const MAX_SCAN = 200;

  // Query evaluations table for sessions not yet convention-checked.
  // Uses NOT IN subquery to exclude already-checked sessions.
  const rows = db
    .prepare(
      `SELECT DISTINCT e.sessionId, e.agent
       FROM evaluations e
       WHERE e.agent != 'evaluator'
